module turbo_encoder (  
    input clk,  
    input rst,  
    input [4:0] data_in,  
    output reg [6:0] encoded_out  
);  
    reg [4:0] interleaved_data;  
    reg [6:0] enc1_out;  
    reg [6:0] enc2_out;  

    // First Encoder
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            enc1_out <= 7'b0;  
        else begin  
            // Simple convolutional encoding (k=3)
            enc1_out[0] <= data_in[0] ^ data_in[1];  
            enc1_out[1] <= data_in[0] ^ data_in[2];  
            enc1_out[2] <= data_in[1] ^ data_in[2];  
            enc1_out[3] <= data_in[2];  
            enc1_out[4] <= data_in[3];  
            enc1_out[5] <= data_in[4];  
            enc1_out[6] <= data_in[4];  
        end  
    end  

    // Interleaver
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            interleaved_data <= 5'b0;  
        else  
            interleaved_data <= {data_in[0], data_in[2], data_in[4], data_in[1], data_in[3]};  
    end  

    // Second Encoder
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            enc2_out <= 7'b0;  
        else begin  
            // Simple convolutional encoding (k=3)
            enc2_out[0] <= interleaved_data[0] ^ interleaved_data[1];  
            enc2_out[1] <= interleaved_data[0] ^ interleaved_data[2];  
            enc2_out[2] <= interleaved_data[1] ^ interleaved_data[2];  
            enc2_out[3] <= interleaved_data[2];  
            enc2_out[4] <= interleaved_data[3];  
            enc2_out[5] <= interleaved_data[4];  
            enc2_out[6] <= interleaved_data[4];  
        end  
    end  

    // Final Output
    always @(posedge clk or posedge rst) begin  
        if (rst)  
            encoded_out <= 7'b0;  
        else  
            encoded_out <= enc1_out ^ enc2_out;  
    end  
endmodule

