module pipeline_adder (  
    input clk,  
    input rst,  
    input [31:0] a,  
    input [31:0] b,  
    output reg [31:0] sum  
);  
    reg [31:0] a_reg [0:6];  
    reg [31:0] b_reg [0:6];  
    reg [31:0] sum_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            sum <= 0;  
        end else begin  
            a_reg[0] <= a;  
            b_reg[0] <= b;  
            a_reg[1] <= a_reg[0];  
            b_reg[1] <= b_reg[0];  
            a_reg[2] <= a_reg[1];  
            b_reg[2] <= b_reg[1];  
            a_reg[3] <= a_reg[2];  
            b_reg[3] <= b_reg[2];  
            a_reg[4] <= a_reg[3];  
            b_reg[4] <= b_reg[3];  
            a_reg[5] <= a_reg[4];  
            b_reg[5] <= b_reg[4];  
            a_reg[6] <= a_reg[5];  
            b_reg[6] <= b_reg[5];  
            sum_reg <= a_reg[6] + b_reg[6];  
            sum <= sum_reg;  
        end  
    end  
endmodule

