    reg [8:0] a01;
    reg [8:0] a02;
    reg [8:0] a10;
    reg [8:0] a11;
    reg [8:0] a12;
    reg [8:0] a20;
    reg [8:0] a21;
    reg [8:0] a22;
    wire [8:0] inv00;
    wire [8:0] inv01;
    wire [8:0] inv02;
    wire [8:0] inv10;
    wire [8:0] inv11;
    wire [8:0] inv12;
    wire [8:0] inv20;
    wire [8:0] inv21;
    wire [8:0] inv22;

    // Test tracking
