        .inv11(inv11),
        .inv12(inv12),
        .inv20(inv20),
        .inv21(inv21),
        .inv22(inv22)
    );
    task testcase001;

    begin
        $display("Running Testcase 001: Identity Matrix");
        a00 = 9'h001; a01 = 9'h000; a02 = 9'h000;
        a10 = 9'h000; a11 = 9'h001; a12 = 9'h000;
        a20 = 9'h000; a21 = 9'h000; a22 = 9'h001;
