module uart_transmitter(
    input wire clk,
    input wire rst,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter IDLE = 2'b00, START_BIT = 2'b01, DATA_BITS = 2'b10, STOP_BIT = 2'b11;
    reg [1:0] state, next_state;
    reg [3:0] bit_count;
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            tx <= 1; // idle high
            bit_count <= 0;
        end else begin
            state <= next_state;
            if (state == START_BIT || state == DATA_BITS || state == STOP_BIT) begin
                tx <= shift_reg[bit_count];
                bit_count <= bit_count + 1;
            end
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start) begin
                    shift_reg <= {1'b1, data_in, 1'b0}; // start bit + data + stop bit
                    bit_count <= 0;
                    busy <= 1;
                    next_state = START_BIT;
                end
            end
            START_BIT: begin
                if (bit_count == 0) begin
                    next_state = DATA_BITS;
                end
            end
            DATA_BITS: begin
                if (bit_count == 9) begin
                    next_state = STOP_BIT;
                end
            end
            STOP_BIT: begin
                if (bit_count == 10) begin
                    busy <= 0;
                    tx <= 1; // return to idle state
                    next_state = IDLE;
                end
            end
        endcase
    end
endmodule

