    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            result <= 16'd1;  
            base <= plaintext;  
            exp <= exponent;  
            mod <= modulus;  
            ciphertext <= 16'd0;  
        end else begin  
            if (exp > 0 && mod > 0) begin  
                for (i = 0; i < 16; i = i + 1) begin  
                    if (exp[i]) begin  
                        result <= (result * base) % mod;  
                    end  
                    base <= (base * base) % mod;  
                end  
                ciphertext <= result;  
            end  
        end  
    end  
endmodule

