module down_counter (
    input wire clk,
    input wire reset,
    output reg [3:0] count
);
    parameter N = 15; // Maximum value for 4-bit counter (0-15)

    always @(posedge clk or posedge reset) begin
        if (reset)
            count <= N; // Reset to maximum value
        else if (count > 0)
            count <= count - 1; // Decrement the count
    end
endmodule

