module uart_transmitter(  
    input wire clk,  
    input wire tx_en,  
    input wire [7:0] data,  
    output reg tx,  
    output reg tx_done  
);  
    reg [3:0] bit_counter;  
    reg [9:0] shift_reg;  
    reg state;  

    parameter IDLE = 1'b0, TRANSMITTING = 1'b1;  

    always @(posedge clk) begin  
        case(state)  
            IDLE: begin  
                tx_done <= 0;  
                if (tx_en) begin  
                    shift_reg <= {1'b1, data, 1'b0}; // Start bit + data + stop bit  
                    bit_counter <= 0;  
                    state <= TRANSMITTING;  
                end  
            end  
            TRANSMITTING: begin  
                if (bit_counter < 10) begin  
                    tx <= shift_reg[bit_counter];  
                    bit_counter <= bit_counter + 1;  
                end else begin  
                    tx_done <= 1;  
                    state <= IDLE;  
                end  
            end  
        endcase  
    end  
endmodule

