module deserializer (
    input wire clk,
    input wire rst,
    input wire serial_in,
    output reg [15:0] parallel_out,
    output reg data_ready
);
    reg [3:0] bit_count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            parallel_out <= 16'b0;
            bit_count <= 4'b0;
            data_ready <= 1'b0;
        end else if (bit_count < 4'd16) begin
            parallel_out <= {serial_in, parallel_out[15:1]};
            bit_count <= bit_count + 1;
            data_ready <= (bit_count == 4'd15); // Set data_ready when the 16th bit is received
        end else begin
            // Once all bits are received, do not change output until reset
            data_ready <= 1'b1;
        end
    end
endmodule

