module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire tx_en,
    input wire [7:0] data_in,
    output reg tx,
    output reg tx_busy
);
    reg [3:0] bit_cnt;
    reg [9:0] shift_reg;
    reg [15:0] clk_div;
    reg sending;

    parameter BAUD_RATE_DIV = 16;  // Adjust this as per your clock frequency

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1;  // Idle state for TX is high
            tx_busy <= 0;
            sending <= 0;
            bit_cnt <= 0;
            clk_div <= 0;
        end else begin
            if (tx_en && !sending) begin
                // Load data into shift register
                shift_reg <= {1'b1, data_in, 1'b0}; // Stop bit, data, start bit
                sending <= 1;  // Start sending
                tx_busy <= 1;
                bit_cnt <= 0;
                clk_div <= 0;
            end

            if (sending) begin
                clk_div <= clk_div + 1;
                if (clk_div == BAUD_RATE_DIV) begin
                    clk_div <= 0; // Reset clk_div
                    tx <= shift_reg[0]; // Transmit the current bit
                    shift_reg <= {1'b0, shift_reg[9:1]}; // Shift right
                    bit_cnt <= bit_cnt + 1;

                    if (bit_cnt == 9) begin
                        sending <= 0; // Transmission complete
                        tx_busy <= 0;
                    end
                end
            end
        end
    end
endmodule

