module viterbi_decoder (  
    input clk,  
    input reset,  
    input [1:0] encoded_input,  
    output reg [1:0] decoded_output,  
    output reg valid_output  
);  
    reg [2:0] state;  
    reg [2:0] next_state;  
    reg [1:0] path_metric [0:3];  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 3'b000;  
            valid_output <= 0;  
        end else begin  
            state <= next_state;  
            valid_output <= 1;  
        end  
    end  

    always @(*) begin  
        // Initialize path metrics  
        for (i = 0; i < 4; i = i + 1)  
            path_metric[i] = 2'b00;  

        // Compute next state based on current state and encoded input  
        case (state)  
            3'b000: begin  
                if (encoded_input == 2'b00) begin  
                    next_state = 3'b000;  
                    decoded_output = 2'b00;  
                end else if (encoded_input == 2'b01) begin  
                    next_state = 3'b001;  
                    decoded_output = 2'b01;  
                end else if (encoded_input == 2'b10) begin  
                    next_state = 3'b010;  
                    decoded_output = 2'b10;  
                end else begin  
                    next_state = 3'b011;  
                    decoded_output = 2'b11;  
                end  
            end  
            3'b001: begin  
                // Similar logic for other states  
                next_state = 3'b000;  
                decoded_output = 2'b01;  
            end  
            3'b010: begin  
                next_state = 3'b001;  
                decoded_output = 2'b10;  
            end  
            3'b011: begin  
                next_state = 3'b010;  
                decoded_output = 2'b11;  
            end  
            default: begin  
                next_state = 3'b000;  
                decoded_output = 2'b00;  
            end  
        endcase  
    end  
endmodule

