module dma_controller(  
    input clk,  
    input start,  
    input [7:0] src_addr,  
    input [7:0] dest_addr,  
    input data_ready,  
    output reg ready  
);  
    reg [7:0] memory [0:255]; // Simple memory array  
    reg [7:0] data;  
    reg [2:0] state; // Simple state machine  

    parameter IDLE = 3'b000, READ = 3'b001, WRITE = 3'b010, COMPLETE = 3'b011;  

    always @(posedge clk) begin  
        case (state)  
            IDLE: begin  
                if (start)  
                    state <= READ;  
            end  
            READ: begin  
                if (data_ready) begin  
                    data <= memory[src_addr];  
                    state <= WRITE;  
                end  
            end  
            WRITE: begin  
                memory[dest_addr] <= data;  
                state <= COMPLETE;  
            end  
            COMPLETE: begin  
                ready <= 1;  
                state <= IDLE;  
            end  
            default: state <= IDLE;  
        endcase  
    end  
endmodule

